          <p className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-600">Al Wakeelo Digital Chambers • Proprietary Intelligence</p>
          {!isLoading && (
            <button 
              onClick={() => downloadAsTxt(brief, `brief-${statute?.shortTitle}-${statute?.section}.txt`)}
