import { useAuth } from "@/hooks/use-auth";
import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Scale, Gavel, Book, FileText, Sparkles, Bookmark, History, FileBadge, Zap, TrendingUp, AlertTriangle } from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { TIER_LIMITS } from "@shared/schema";

type UsageData = {
  tier: string;
  tierLabel: string;
  tierDescription: string;
  monthlyLimit: number;
  used: number;
  remaining: number;
  percentage: number;
};

export default function DashboardPage() {
  const { user } = useAuth();
  const { data: bookmarks } = useQuery<any[]>({ queryKey: ["/api/bookmarks"] });
  const { data: history } = useQuery<any[]>({ queryKey: ["/api/search-history"] });
  const { data: documents } = useQuery<any[]>({ queryKey: ["/api/documents"] });
  const { data: threads } = useQuery<any[]>({ queryKey: ["/api/threads"] });
  const { data: usage } = useQuery<UsageData>({ queryKey: ["/api/usage"] });

  const stats = [
    { label: "Active Sessions", value: threads?.length || 0, icon: Scale, color: "text-amber-500" },
    { label: "Saved Strategies", value: bookmarks?.length || 0, icon: Bookmark, color: "text-blue-400" },
    { label: "Search History", value: history?.length || 0, icon: History, color: "text-emerald-400" },
    { label: "Registry Files", value: documents?.length || 0, icon: FileBadge, color: "text-purple-400" },
  ];

  const quickActions = [
    { label: "Judgment Search", icon: Gavel, href: "/judgment-search", desc: "Search Pakistani case law" },
    { label: "Statute Search", icon: Book, href: "/statute-search", desc: "Browse legal statutes" },
    { label: "Al Wakeelo Engine", icon: Scale, href: "/al-wakeelo", desc: "Consult your AI advocate" },
    { label: "Legal Drafting", icon: FileText, href: "/legal-drafting", desc: "Draft legal documents" },
    { label: "Contract Drafting", icon: Sparkles, href: "/contract-drafting", desc: "Generate contracts" },
    { label: "Case Documents", icon: FileBadge, href: "/case-documents", desc: "Browse case files" },
  ];

  const isNearLimit = usage && usage.percentage >= 80;
  const isAtLimit = usage && usage.percentage >= 100;

  return (
    <div className="space-y-10 fade-in" data-testid="dashboard-page">
      <div className="p-12 md:p-16 bg-gradient-to-br from-amber-500 to-amber-600 rounded-[3rem] text-slate-950 shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-12 opacity-10 group-hover:scale-110 group-hover:rotate-12 transition-all duration-1000">
          <Scale size={240} />
        </div>
        <div className="relative z-10">
          <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-4 text-slate-900/60">
            Chambers Secure Protocol
          </p>
          <h2 className="text-4xl md:text-6xl font-bold mb-6 tracking-tighter italic leading-none" style={{ fontFamily: "'Playfair Display', serif" }}>
            "Justice is for all,<br />but wins are for the smart."
          </h2>
          <p className="text-lg font-medium opacity-80 max-w-2xl leading-relaxed">
            Welcome back, {user?.firstName || "Advocate"}. Al Wakeelo core engine synchronized. Chambers vaults and registries are online.
          </p>
        </div>
      </div>

      {usage && (
        <div className={`p-8 rounded-[2.5rem] border shadow-xl ${isAtLimit ? "bg-red-950/30 border-red-800/50" : isNearLimit ? "bg-amber-950/30 border-amber-800/50" : "bg-[#1e293b] border-slate-800"}`} data-testid="usage-panel">
          <div className="flex items-center gap-4 mb-6">
            {isAtLimit ? (
              <AlertTriangle size={18} className="text-red-400" />
            ) : (
              <TrendingUp size={18} className="text-amber-500" />
            )}
            <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-amber-500">
              Monthly Usage — {usage.tierLabel} Plan
            </h3>
            <div className="flex-1 h-px bg-slate-800" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
            <div className="md:col-span-2 space-y-4">
              <div className="flex items-end justify-between gap-4">
                <div>
                  <p className="text-3xl font-black text-white" data-testid="text-usage-count">
                    {usage.used}
                    <span className="text-lg text-slate-500 font-medium"> / {usage.monthlyLimit === 999999 ? "Unlimited" : usage.monthlyLimit}</span>
                  </p>
                  <p className="text-[9px] font-black uppercase tracking-widest text-slate-500 mt-1">
                    AI Queries This Month
                  </p>
                </div>
                <p className="text-sm font-bold text-slate-400" data-testid="text-usage-remaining">
                  {usage.remaining === 999999 ? "Unlimited" : usage.remaining} remaining
                </p>
              </div>
              <Progress
                value={usage.monthlyLimit === 999999 ? 0 : usage.percentage}
                className="h-3 bg-slate-800 rounded-full"
                data-testid="progress-usage"
              />
            </div>

            <div className="flex flex-col items-center gap-3 p-6 bg-slate-800/50 rounded-2xl">
              <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Current Plan</p>
              <p className="text-xl font-black text-amber-500" data-testid="text-tier-label">{usage.tierLabel}</p>
              <p className="text-[10px] text-slate-400 text-center">{usage.tierDescription}</p>
            </div>
          </div>

          {isAtLimit && (
            <div className="mt-6 p-4 bg-red-900/30 border border-red-800/30 rounded-xl" data-testid="alert-limit-reached">
              <p className="text-sm text-red-300 font-medium">
                You have reached your monthly query limit. Upgrade your plan to continue using AI features.
              </p>
            </div>
          )}

          {isNearLimit && !isAtLimit && (
            <div className="mt-6 p-4 bg-amber-900/30 border border-amber-800/30 rounded-xl" data-testid="alert-near-limit">
              <p className="text-sm text-amber-300 font-medium">
                You are approaching your monthly query limit ({usage.remaining} queries remaining). Consider upgrading your plan.
              </p>
            </div>
          )}
        </div>
      )}

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        {stats.map((stat) => {
          const Icon = stat.icon;
          return (
            <div key={stat.label} className="bg-[#1e293b] border border-slate-800 rounded-[2rem] p-6 md:p-8 shadow-xl" data-testid={`stat-${stat.label.toLowerCase().replace(/\s+/g, '-')}`}>
              <div className="flex items-center gap-3 mb-4">
                <div className={`p-2.5 bg-slate-800 rounded-xl ${stat.color}`}><Icon size={18} /></div>
              </div>
              <p className="text-3xl font-black text-white mb-1">{stat.value}</p>
              <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">{stat.label}</p>
            </div>
          );
        })}
      </div>

      <div>
        <div className="flex items-center gap-4 mb-8">
          <Zap size={18} className="text-amber-500" />
          <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-amber-500">Quick Actions</h3>
          <div className="flex-1 h-px bg-slate-800" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {quickActions.map((action) => {
            const Icon = action.icon;
            return (
              <Link key={action.label} href={action.href}>
                <div className="p-8 bg-[#1e293b] border border-slate-800 rounded-[2.5rem] shadow-xl hover:border-amber-500/30 transition-all cursor-pointer group" data-testid={`action-${action.label.toLowerCase().replace(/\s+/g, '-')}`}>
                  <div className="flex items-center gap-4 mb-4">
                    <div className="p-3 bg-amber-500/10 text-amber-500 rounded-xl group-hover:bg-amber-500 group-hover:text-slate-950 transition-all"><Icon size={20} /></div>
                    <h4 className="text-sm font-bold text-white">{action.label}</h4>
                  </div>
                  <p className="text-xs text-slate-500 leading-relaxed">{action.desc}</p>
                </div>
              </Link>
            );
          })}
        </div>
      </div>
    </div>
  );
}

